                    s1 = wasm_f64x2_add(s1, wasm_f64x2_mul(c, wasm_v128_load(pr + 2)));
                    s2 = wasm_f64x2_add(s2, wasm_f64x2_mul(c, wasm_v128_load(pr + 4)));
